const INVALID:f64=-1.0e300;
export fn simple_neural_network(values:?[*]const i64,length:usize) f64{if(values==null or length!=3)return INVALID;const p=values.?;const expected=p[0];const initial=p[1];const count=p[2];if(expected<0 or expected>100 or initial<1 or initial>199 or @mod(initial,2)!=1 or count<1 or count>65536)return INVALID;const target=@as(f64,@floatFromInt(expected))/100.0;var weight=@as(f64,@floatFromInt(initial));var layer:f64=0;var i:i64=0;while(i<count):(i+=1){layer=1.0/(1.0+@exp(-0.02*weight));const error=target-layer;const delta=error*layer*(1.0-layer);weight+=0.02*delta;}return layer*100.0;}
